CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS businesses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,business_name VARCHAR(160) NOT NULL,profile_image TEXT);
CREATE TABLE IF NOT EXISTS products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,category VARCHAR(80) DEFAULT 'General',cost_price NUMERIC(12,2) NOT NULL,selling_price NUMERIC(12,2) NOT NULL,stock INTEGER NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_business_id ON products(business_id);
CREATE TABLE IF NOT EXISTS customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,phone VARCHAR(30),email VARCHAR(160),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_customers_business_id ON customers(business_id);
CREATE TABLE IF NOT EXISTS orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,customer_id BIGINT NOT NULL REFERENCES customers(id),order_date DATE NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'completed' CHECK (status IN ('completed','cancelled')),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_orders_business_date ON orders(business_id,order_date);
CREATE TABLE IF NOT EXISTS order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL,cost_price NUMERIC(12,2) NOT NULL,selling_price NUMERIC(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS expense_categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,name VARCHAR(80) NOT NULL,CONSTRAINT uq_expense_category_business_name UNIQUE(business_id,name));
CREATE TABLE IF NOT EXISTS expenses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,business_id BIGINT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,category_id BIGINT NOT NULL REFERENCES expense_categories(id),amount NUMERIC(12,2) NOT NULL,expense_date DATE NOT NULL,description VARCHAR(255));
CREATE INDEX IF NOT EXISTS idx_expenses_business_date ON expenses(business_id,expense_date);
